 public static void Main(string[] args){var report=new Dictionary<string,object>();report["service"]="Antigravity";Process p=null;IntPtr job=IntPtr.Zero;var w=Stopwatch.StartNew();try{if(args.Length!=1||Path.GetFileName(args[0])!="agy.exe"||!File.Exists(args[0]))throw new Probe.Bad("cli_missing");job=CreateJobObject(IntPtr.Zero,null);if(job==IntPtr.Zero)throw new Probe.Bad("job_unavailable");var lim=new Limits();lim.basic.flags=0x2000|0x20;lim.basic.priority=0x4000;if(!SetInformationJobObject(job,9,ref lim,(uint)Marshal.SizeOf(typeof(Limits))))throw new Probe.Bad("job_config_failed");var si=new ProcessStartInfo(args[0],"-p /credits --output-format json --print-timeout 15s");si.WorkingDirectory=AppDomain.CurrentDomain.BaseDirectory;si.UseShellExecute=false;si.CreateNoWindow=true;si.RedirectStandardOutput=true;si.RedirectStandardError=true;si.StandardOutputEncoding=Encoding.UTF8;si.StandardErrorEncoding=Encoding.UTF8;p=new Process{StartInfo=si};p.Start();if(!AssignProcessToJobObject(job,p.Handle)){try{p.Kill();}catch{}throw new Probe.Bad("job_assignment_failed");}var ot=new Thread(delegate(){Drain(p.StandardOutput,true,od);});ot.IsBackground=true;ot.Start();var et=new Thread(delegate(){Drain(p.StandardError,false,ed);});et.IsBackground=true;et.Start();long observedPeak=0;double observedCpu=0;bool exited=false;while(w.ElapsedMilliseconds<20000){try{p.Refresh();observedPeak=Math.Max(observedPeak,p.PeakWorkingSet64);observedCpu=p.TotalProcessorTime.TotalMilliseconds;}catch{}if(Interlocked.CompareExchange(ref overflow,0,0)!=0)throw new Probe.Bad("cli_output_too_large");if(p.WaitForExit(100)){exited=true;break;}}if(!exited)throw new Probe.Bad("cli_deadline_exceeded");report["cli_exit_code"]=p.ExitCode;report["cli_observed_peak_working_set_bytes"]=observedPeak;report["cli_observed_cpu_ms"]=observedCpu;CloseHandle(job);job=IntPtr.Zero;if(!od.WaitOne(1000)||!ed.WaitOne(1000))throw new Probe.Bad("cli_pipe_deadline");if(overflow!=0)throw new Probe.Bad("cli_output_too_large");if